item.aggregated_output:
// Package tracking injects a visitor tracking snippet into the console's pages.
//
// The console is served under a content security policy that allows scripts
// from its own origin only, so a tracking snippet cannot simply be pasted into
// the page: the browser refuses it and the administrator sees an empty
// dashboard with no explanation. This package produces both halves of what a
// snippet needs to run under that policy — the markup with a per-request nonce
// on every script tag, and the extra policy sources read out of the snippet —
// without ever loosening the policy with 'unsafe-inline', which would stay
// loose after tracking is switched off.
//
// Momento, the in-house collector, comes first because it is the only provider
// that keeps the data inside the building. Through the same-origin proxy under
// ProxyPath no external origin appears in the policy at all.
package tracking

import (
	"errors"
	"fmt"
	"html"
	"net/url"
	"strings"
	"unicode/utf8"
)

// SettingKey is the system_settings row these settings live in.
const SettingKey = "tracking"

// Providers, in the order the console offers them.
const (
	ProviderNone    = "none"
	ProviderMomento = "momento"
	ProviderGA4     = "ga4"
	ProviderGTM     = "gtm"
	ProviderMatomo  = "matomo"
	ProviderCustom  = "custom"
)

// Providers lists every provider the settings accept.
var Providers = []string{ProviderNone, ProviderMomento, ProviderGA4, ProviderGTM, ProviderMatomo, ProviderCustom}

// MaxSnippetBytes bounds a pasted snippet. A loader is a few hundred bytes; a
// snippet past this size is a page, not a tracker.
const MaxSnippetBytes = 8 * 1024

// MaxAllowedHostRunes bounds one entry of the allow list. Whatever an
// administrator writes there is joined into the Content-Security-Policy header
// of every page as its own source, without passing through originOf as the
// provider addresses do, so its size is the size of a header everybody's
// browser then has to read. An origin is a scheme, a host and perhaps a port:
// 300 runes leaves room above the 253 characters a DNS name can hold — the same
// number, for the same reason, as the origin limit in violations.go — and cuts
// nothing anybody would want to allow. It is counted in runes because an
// address can be written in Korean.
const MaxAllowedHostRunes = 300

// MaxAllowedHostEntries and MaxAllowedHostsTotalRunes bound the allow list
// itself, which the limit on one entry does not. PolicySources writes every
// entry into img-src, connect-src and script-src alike, so a list of n runes
// arrives in the header as 3n plus a space before each source, and nothing else
// stands between a settings document and that header: filled to the body limit
// the settings route accepts, the console would answer every page with a header
// of several megabytes, which a reverse proxy or a browser refuses — taking the
// console down rather than the tracking.
//
// 4096 runes across at most 64 entries holds the tripled list to 12480 runes,
// which is a little under 12.5 kilobytes while the entries are written in ASCII
// and up to four times that when they are not — see MaxSnippetOriginEntries
// below for what these limits do and do not hold in bytes — against the eight
// kilobytes a reverse proxy commonly keeps in reserve for a response's headers.
// Neither number is a measurement of anybody's allow list, so both are set well
// past use: 64 origins is more than a console injecting one snippet plausibly
// needs, 4096 runes is some 130 origins of the length origins really run to,
// and the longest list this package's tests fix as
// acceptable — forty entries of eighty-one runes — sits comfortably inside both,
// so switching these on refuses nothing that was working. Both count the way the
// per-entry limit counts, in runes over the entries as they are stored, because
// an address can be written in Korean; and both refuse rather than trim, since
// an origin an administrator reads back has to be the one they allowed.
const (
	MaxAllowedHostEntries     = 64
	MaxAllowedHostsTotalRunes = 4096
)

// MaxSnippetOriginEntries and MaxSnippetOriginsTotalRunes bound the origins
// read out of a pasted snippet, which the allow list's limits do not: the
// ProviderCustom branch of PolicySources hands every address SnippetOrigins
// found to the same three directives the list goes into, so a snippet's
// addresses are tripled into the header exactly as an administrator's list is.
// The only limit a snippet carried is MaxSnippetBytes, and a count of bytes of
// markup says nothing about how many addresses are written in them: filled
// with the cheapest origin that parses, 8180 bytes of snippet name 592 of them
// and build a policy header of 24813 bytes, measured, which is the same
// refusal by a reverse proxy — and the same console taken down rather than the
// tracking — that the list's limits exist to prevent.
//
// 1024 runes across at most 32 entries holds that tripled to 3168 runes,
// which added to the tripled allow list and the base policy leaves these two
// settings at 15921 runes of header together, measured, inside the sixteen
// kilobytes internal/api's tests name as the budget — in runes, which is not
// the unit that budget is about. A proxy counts the bytes it has to carry, and
// these limits count runes for the reason the per-entry limit does, because an
// address can be written in Korean: the same worst case of 15921 runes measures
// 15921 bytes with the addresses in ASCII, 33513 with them in Korean and 42309
// with letters that take four bytes each, all three measured and all three
// accepted. So what these two limits hold under the budget is the runes they
// contribute, and the byte figure follows the script an administrator writes
// in, up to four times the runes.
//
// That rune bound is also only the worst case these two limits reach and not
// the worst case a settings document can build: a provider's address reaches
// the same three directives through originOf, and no limit here or in Validate
// measures its length, so Provider=matomo with an eight thousand rune
// MatomoURL — or that address as MomentoURL with the proxy off — is accepted
// and builds a 24339 byte header, measured, the same order as the snippet this
// limit refuses. Bounding the header in bytes means bounding those addresses
// and spending the budget in bytes here too; until then what is bounded is the
// runes these two settings contribute, and the header as a whole is not.
//
// Both numbers here are set well past use for the same reason the list's are:
// a loader names the script it fetches, the endpoint it posts to and perhaps a
// pixel, so two to five origins is what a real snippet comes with, and 1024
// runes is some thirty origins of the length origins really run to. A single
// address is bounded by the total rather than by the count, which is the half
// that matters — one origin of eight thousand runes is one entry, and the count
// alone would wave it through. Both refuse rather than trim: a snippet an
// administrator reads back has to be the one they pasted.
const (
	MaxSnippetOriginEntries     = 32
	MaxSnippetOriginsTotalRunes = 1024
)

// ProxyPath is where the console forwards Momento's tracker and collector, so
// a browser talks to the collector through the console's own origin.
const ProxyPath = "/momento"

// ReportPath receives the browser's reports of what the policy blocked. It is
// only written into the policy while tracking is on.
const ReportPath = "/api/v1/tracking/csp-report"

// Settings is what an administrator configures. Field names are the console's
// keys; the settings-key sweep in internal/api checks that each one is read.
type Settings struct {
	Enabled  bool   `json:"enabled"`
	Provider string `json:"provider"`
	// MomentoURL is the collector, for example https://momento.corp.example.
	MomentoURL    string `json:"momentoUrl"`
	MomentoSiteID string `json:"momentoSiteId"`
	// MomentoProxy sends the tracker and its events through ProxyPath on this
	// origin instead of straight to the collector. On by default: with it the
	// policy names no external origin, which is the whole difficulty.
	MomentoProxy bool `json:"momentoProxy"`
	// MomentoEnvironment is what the collector files the visits under.
	MomentoEnvironment string `json:"momentoEnvironment"`
	// MeasurementID is the GA4 or GTM id.
	MeasurementID string `json:"measurementId"`
	MatomoURL     string `json:"matomoUrl"`
	MatomoSiteID  string `json:"matomoSiteId"`
	// CustomSnippet is pasted markup, injected as written with a nonce added.
	CustomSnippet string `json:"customSnippet"`
	// AllowedHosts is where an administrator adds an origin the snippet did not
	// name, one per line or comma.
	AllowedHosts string `json:"allowedHosts"`
	// IncludeAdmin extends tracking to the administration screens. Off by
	// default: console traffic is rarely the visitor data anybody wants.
	IncludeAdmin bool `json:"includeAdmin"`
	// Placement is "head" or "body".
	Placement string `json:"placement"`
}

// Defaults are what an unconfigured deployment gets: nothing injected, nothing
// added to the policy.
func Defaults() Settings {
	return Settings{Provider: ProviderNone, MomentoProxy: true, MomentoEnvironment: "prd", Placement: "head"}
}

// Normalized trims what an administrator typed and fills the fields that have
// a fixed set of values.
func (s Settings) Normalized() Settings {
	s.Provider = strings.ToLower(strings.TrimSpace(s.Provider))
	if s.Provider == "" {
		s.Provider = ProviderNone
	}
	s.MomentoURL = strings.TrimRight(strings.TrimSpace(s.MomentoURL), "/")
	s.MomentoSiteID = strings.TrimSpace(s.MomentoSiteID)
	s.MomentoEnvironment = strings.TrimSpace(s.MomentoEnvironment)
	if s.MomentoEnvironment == "" {
		s.MomentoEnvironment = "prd"
	}
	s.MeasurementID = strings.TrimSpace(s.MeasurementID)
	s.MatomoURL = strings.TrimRight(strings.TrimSpace(s.MatomoURL), "/")
	s.MatomoSiteID = strings.TrimSpace(s.MatomoSiteID)
	s.CustomSnippet = strings.TrimSpace(s.CustomSnippet)
	s.Placement = strings.ToLower(strings.TrimSpace(s.Placement))
	if s.Placement != "body" {
		s.Placement = "head"
	}
	return s
}

// Validate reports what is missing for the chosen provider. It is called on
// the way in, so a snippet that cannot work is refused at the form rather than
// discovered as an empty dashboard.
func (s Settings) Validate() error {
	s = s.Normalized()
	if !containsString(Providers, s.Provider) {
		return fmt.Errorf("추적 제공자는 %s 중 하나여야 합니다", strings.Join(Providers, ", "))
	}
	if len(s.CustomSnippet) > MaxSnippetBytes {
		return fmt.Errorf("추적 코드는 %d바이트를 넘을 수 없습니다", MaxSnippetBytes)
	}
	// The addresses inside that markup are what reach the header, three times
	// each, so they are measured here beside the limit on the markup rather than
	// under the provider switch below: a snippet stored while the provider points
	// somewhere else is a snippet a later write only has to flip the provider to
	// serve, and a limit it escaped would refuse that write instead of this one.
	// The message names what to shorten, because the administrator reading it has
	// a snippet in front of them and no view of the header it builds.
	origins := SnippetOrigins(s.CustomSnippet)
	if len(origins) > MaxSnippetOriginEntries {
		return fmt.Errorf("추적 코드가 명명한 출처는 %d개까지만 쓸 수 있습니다 (%d개) — 추적 코드의 주소 수를 줄여 주세요", MaxSnippetOriginEntries, len(origins))
	}
	originRunes := 0
	for _, origin := range origins {
		originRunes += utf8.RuneCountInString(origin)
	}
	if originRunes > MaxSnippetOriginsTotalRunes {
		return fmt.Errorf("추적 코드가 명명한 출처 전체는 %d자를 넘을 수 없습니다 (%d자) — 추적 코드의 주소를 줄여 주세요", MaxSnippetOriginsTotalRunes, originRunes)
	}
	if len(s.MomentoEnvironment) > 32 || strings.ContainsAny(s.MomentoEnvironment, "\"'<>&") {
		return errors.New("Momento 환경 이름을 확인해 주세요 (32자 이하, 따옴표·꺾쇠 없이)")
	}
	// Each entry here becomes a source in the policy header of every page as it
	// was typed — the provider addresses go through originOf, these do not — so
	// the two characters a source must not contain are checked where the entry
	// is written rather than where the header is built: a semicolon would close
	// the directive the entry sits in and open one of the writer's choosing for
	// the whole console, and there is nothing to stop a pasted line from being
	// as long as the paste was. Entries already stored are refused rather than
	// rewritten, because an origin an administrator reads back has to be the one
	// they allowed.
	hosts := splitHosts(s.AllowedHosts)
	for _, host := range hosts {
		if originOf(host) == "" || !strings.HasPrefix(strings.ToLower(host), "http") {
			return fmt.Errorf("허용 출처 %q 는 https://호스트 형태여야 합니다", host)
		}
		if strings.ContainsRune(host, ';') {
			return fmt.Errorf("허용 출처 %q 에는 세미콜론을 쓸 수 없습니다 — 정책 지시문이 거기서 끝납니다", host)
		}
		if count := utf8.RuneCountInString(host); count > MaxAllowedHostRunes {
			return fmt.Errorf("허용 출처 %q 는 %d자를 넘을 수 없습니다 (%d자)", cutRunes(host, MaxAllowedHostRunes), MaxAllowedHostRunes, count)
		}
	}
	// Each entry being an origin and no longer than one says nothing about how
	// many of them there are, and it is the whole list that is written into three
	// directives of the header every page carries. The list is measured after its
	// entries are checked so that a list with a bad entry in it still names the
	// entry, which is the message an administrator can act on.
	if len(hosts) > MaxAllowedHostEntries {
		return fmt.Errorf("허용 출처 목록에는 %d개까지만 넣을 수 있습니다 (%d개)", MaxAllowedHostEntries, len(hosts))
	}
	total := 0
	for _, host := range hosts {
		total += utf8.RuneCountInString(host)
	}
	if total > MaxAllowedHostsTotalRunes {
		return fmt.Errorf("허용 출처 목록 전체는 %d자를 넘을 수 없습니다 (%d자)", MaxAllowedHostsTotalRunes, total)
	}
	if !s.Enabled {
		return nil
	}
	switch s.Provider {
	case ProviderNone:
		return nil
	case ProviderMomento:
		if s.MomentoURL == "" || s.MomentoSiteID == "" {
			return errors.New("Momento 수집기 주소와 사이트 id 가 필요합니다")
		}
		if originOf(s.MomentoURL) == "" || !strings.HasPrefix(strings.ToLower(s.MomentoURL), "http") {
			return errors.New("Momento 수집기 주소는 http(s)://호스트 형태여야 합니다")
		}
	case ProviderGA4, ProviderGTM:
		if s.MeasurementID == "" {
			return errors.New("GA4 · GTM 에는 measurement id 가 필요합니다")
		}
	case ProviderMatomo:
		if s.MatomoURL == "" || s.MatomoSiteID == "" {
			return errors.New("Matomo 주소와 사이트 id 가 필요합니다")
		}
		if originOf(s.MatomoURL) == "" || !strings.HasPrefix(strings.ToLower(s.MatomoURL), "http") {
			return errors.New("Matomo 주소는 http(s)://호스트 형태여야 합니다")
		}
	case ProviderCustom:
		if s.CustomSnippet == "" {
			return errors.New("붙여 넣을 추적 코드가 비어 있습니다")
		}
	}
	return nil
}

// Active reports whether a page at this path should carry the snippet.
func (s Settings) Active(path string) bool {
	s = s.Normalized()
	if !s.Enabled || s.Provider == ProviderNone {
		return false
	}
	if !s.IncludeAdmin && (path == "/admin" || strings.HasPrefix(path, "/admin/")) {
		return false
	}
	return strings.TrimSpace(s.Snippet("")) != ""
package tracking

import (
	"fmt"
	"strings"
	"testing"
	"time"
	"unicode/utf8"
)

// A fresh deployment has nothing switched on, and nothing in the policy.
func TestDefaultsInjectNothing(t *testing.T) {
	settings := Defaults()
	if settings.Enabled || settings.Active("/") || settings.ProxyActive() {
		t.Fatal("tracking is on by default")
	}
	if settings.Snippet("n") != "" {
		t.Fatalf("a default configuration renders a snippet: %q", settings.Snippet("n"))
	}
	sources := settings.PolicySources()
	if len(sources.Scripts)+len(sources.Connects)+len(sources.Images) != 0 {
		t.Fatalf("a default configuration adds policy sources: %+v", sources)
	}
	if err := settings.Validate(); err != nil {
		t.Fatalf("the defaults do not validate: %v", err)
	}
}

// Momento through the proxy is the recommended shape: the tracker loads from
// this origin and reports to this origin, so the policy names nobody else.
func TestMomentoThroughTheProxyNamesNoExternalOrigin(t *testing.T) {
	settings := Settings{Enabled: true, Provider: ProviderMomento, MomentoURL: "https://momento.corp.example/", MomentoSiteID: "agenthub", MomentoProxy: true, MomentoEnvironment: "prd"}
	snippet := settings.Snippet("abc")
	for _, want := range []string{`src="/momento/tracker.js"`, `data-endpoint="/momento"`, `data-site-id="agenthub"`, `data-environment="prd"`, `data-contract-version="1"`, `nonce="abc"`} {
		if !strings.Contains(snippet, want) {
			t.Errorf("snippet lacks %s:\n%s", want, snippet)
		}
	}
	if strings.Contains(snippet, "momento.corp.example") {
		t.Errorf("the collector's address leaked into the proxied snippet:\n%s", snippet)
	}
	if sources := settings.PolicySources(); len(sources.Scripts)+len(sources.Connects)+len(sources.Images) != 0 {
		t.Errorf("the proxy shape still adds policy sources: %+v", sources)
	}
	if !settings.ProxyActive() {
		t.Error("the proxy is not active")
	}

	// Sent straight to the collector, its origin has to be in every directive.
	settings.MomentoProxy = false
	snippet = settings.Snippet("abc")
	if !strings.Contains(snippet, `src="https://momento.corp.example/tracker.js"`) || strings.Contains(snippet, "data-endpoint") {
		t.Errorf("the direct snippet does not load from the collector:\n%s", snippet)
	}
	sources := settings.PolicySources()
	for name, group := range map[string][]string{"script": sources.Scripts, "connect": sources.Connects, "img": sources.Images} {
		if len(group) != 1 || group[0] != "https://momento.corp.example" {
			t.Errorf("%s-src should name the collector once, got %v", name, group)
		}
	}
	if settings.ProxyActive() {
		t.Error("the proxy is active for a direct configuration")
	}
}

// Every script tag gets the nonce, including the ones inside a pasted snippet,
// and a tag that already carries one is left alone.
func TestEveryScriptTagCarriesTheNonce(t *testing.T) {
	settings := Settings{Enabled: true, Provider: ProviderCustom, CustomSnippet: `<script src="https://t.corp.example/t.js"></script>
<SCRIPT>window.__t=1</SCRIPT>
<script nonce="theirs">x()</script>`}
	snippet := settings.Snippet("ours")
	if got := strings.Count(snippet, `nonce="ours"`); got != 2 {
		t.Errorf("expected the nonce on 2 tags, found %d:\n%s", got, snippet)
	}
	if !strings.Contains(snippet, `<script nonce="theirs">`) {
		t.Errorf("a tag with its own nonce was rewritten:\n%s", snippet)
	}
	for _, provider := range []string{ProviderGA4, ProviderGTM, ProviderMatomo} {
		settings := Settings{Enabled: true, Provider: provider, MeasurementID: "G-1", MatomoURL: "https://matomo.corp.example", MatomoSiteID: "3"}
		snippet := settings.Snippet("ours")
		if tags, nonces := strings.Count(strings.ToLower(snippet), "<script"), strings.Count(snippet, `nonce="ours"`); tags == 0 || tags != nonces {
			t.Errorf("%s: %d script tags, %d nonces:\n%s", provider, tags, nonces, snippet)
		}
	}
}

// A pasted snippet names the addresses it loads and reports to; those are
// what the policy has to allow, and they are read out of the snippet rather
// than out of a browser console.
func TestOriginsAreReadOutOfAPastedSnippet(t *testing.T) {
	snippet := `<script src="https://momento.corp.example/tracker.js"></script>
<script>window.__t={endpoint:"https://momento.corp.example/collect/v1/events",pixel:'https://pixel.corp.example/p.gif?id=1'};
fetch("HTTP://insecure.corp.example:8080/x")</script>`
	origins := SnippetOrigins(snippet)
	want := []string{"https://momento.corp.example", "https://pixel.corp.example", "http://insecure.corp.example:8080"}
	if strings.Join(origins, " ") != strings.Join(want, " ") {
		t.Fatalf("origins = %v, want %v", origins, want)
	}
	settings := Settings{Enabled: true, Provider: ProviderCustom, CustomSnippet: snippet, AllowedHosts: "https://extra.corp.example, https://other.corp.example/\nhttps://extra.corp.example"}
	sources := settings.PolicySources()
	if strings.Join(sources.Scripts, " ") != strings.Join(append(want, "https://extra.corp.example", "https://other.corp.example", "https://extra.corp.example"), " ") {
		t.Fatalf("script sources = %v", sources.Scripts)
	}
}

func TestValidationRefusesWhatCannotWork(t *testing.T) {
	cases := map[string]Settings{
		"unknown provider":    {Enabled: true, Provider: "piwik"},
		"momento without id":  {Enabled: true, Provider: ProviderMomento, MomentoURL: "https://momento.corp.example"},
		"momento without url": {Enabled: true, Provider: ProviderMomento, MomentoSiteID: "x"},
		"momento bad url":     {Enabled: true, Provider: ProviderMomento, MomentoURL: "momento.corp.example", MomentoSiteID: "x"},
		"ga4 without id":      {Enabled: true, Provider: ProviderGA4},
		"matomo without url":  {Enabled: true, Provider: ProviderMatomo, MatomoSiteID: "1"},
		"custom empty":        {Enabled: true, Provider: ProviderCustom},
		"custom too large":    {Enabled: true, Provider: ProviderCustom, CustomSnippet: "<script>" + strings.Repeat("x", MaxSnippetBytes) + "</script>"},
		"bad allowed host":    {Provider: ProviderNone, AllowedHosts: "momento.corp.example"},
		"environment markup":  {Enabled: true, Provider: ProviderMomento, MomentoURL: "https://m.corp.example", MomentoSiteID: "x", MomentoEnvironment: `"><script>`},
	}
	for name, settings := range cases {
		if err := settings.Validate(); err == nil {
			t.Errorf("%s was accepted", name)
		}
	}
	// The size limit applies whether or not the snippet is in use: a stored
	// page-sized blob is a page-sized blob.
	oversized := Settings{Provider: ProviderNone, CustomSnippet: strings.Repeat("x", MaxSnippetBytes+1)}
	if err := oversized.Validate(); err == nil {
		t.Error("an oversized snippet was stored because tracking was off")
	}
	// And a switched-off configuration with half-filled fields is fine — the
	// administrator may be filling the form in before turning it on.
	if err := (Settings{Provider: ProviderMomento, MomentoURL: "https://m.corp.example"}).Validate(); err != nil {
		t.Errorf("a switched-off configuration was refused: %v", err)
	}
	if err := (Settings{Enabled: true, Provider: ProviderMomento, MomentoURL: "https://m.corp.example", MomentoSiteID: "x", AllowedHosts: "https://a.corp.example\nhttps://b.corp.example:8443"}).Validate(); err != nil {
		t.Errorf("a complete configuration was refused: %v", err)
	}
}

// An allow-list entry is written into the policy header of every page exactly
// as it was typed, so an entry carrying a semicolon would end the directive it
// sits in and open one of its own choosing for the whole console. It is refused
// where it is typed rather than rewritten, because an entry that was already
// stored has to keep meaning what it meant.
func TestAnAllowedHostCannotOpenAPolicyDirectiveOfItsOwn(t *testing.T) {
	refused := map[string]string{
		"a semicolon opens a new directive": "https://a.corp.example/;script-src-elem",
		"a semicolon after a good entry":    "https://a.corp.example\nhttps://b.corp.example/;object-src",
		"a semicolon at the end":            "https://a.corp.example/x;",
		"longer than any host can be":       "https://" + strings.Repeat("a", MaxAllowedHostRunes) + ".corp.example",
		"long with nothing to break it up":  strings.Repeat("https://a.corp.example/", 20),
	}
	for name, hosts := range refused {
		err := (Settings{Provider: ProviderNone, AllowedHosts: hosts}).Validate()
		if err == nil {
			t.Errorf("%s was accepted: %q", name, hosts)
			continue
		}
		if !strings.HasPrefix(err.Error(), "허용 출처 ") {
			t.Errorf("%s: the message does not say which entry is wrong: %v", name, err)
		}
	}

	// What already worked keeps working: a wildcard host, a port, a trailing
	// slash, and the comma-and-newline mixture the console's textarea produces.
	accepted := map[string]string{
		"wildcard":         "https://*.corp.example",
		"port":             "https://b.corp.example:8443",
		"trailing slash":   "https://other.corp.example/",
		"mixed separators": "https://a.corp.example, https://b.corp.example:8443\nhttps://*.corp.example\r\nhttps://c.corp.example/",
		// The limit counts letters, not bytes: this is 223 runes and 623 bytes,
		// and a Korean address must not be refused for being written in Korean.
		"korean path": "https://a.corp.example/" + strings.Repeat("가", 200),
	}
	for name, hosts := range accepted {
		if err := (Settings{Provider: ProviderNone, AllowedHosts: hosts}).Validate(); err != nil {
			t.Errorf("%s was refused: %v", name, err)
		}
	}

	// The limit is on one entry, not on the list: an administrator with many
	// origins is not asked to choose between them.
	var many []string
	for range 40 {
		many = append(many, "https://"+strings.Repeat("a", 60)+".corp.example")
	}
	if err := (Settings{Provider: ProviderNone, AllowedHosts: strings.Join(many, "\n")}).Validate(); err != nil {
		t.Errorf("a long list of short entries was refused: %v", err)
	}

	// And what the console offers to allow with one click still goes in. A
	// listed origin is originOf's output cut at the same number of runes, so the
	// button beside a report can never produce an entry this refuses — which
	// would be a refusal the administrator has no way to act on.
	recorder := NewRecorder()
	recorder.Record("https://"+strings.Repeat("b", 16*1024)+".example/collect;script-src", "connect-src", "/")
	recorder.Record("https://pixel.corp.example:8443/p.gif", "img-src", "/")
